def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = list(packages)
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        features = set(data.get("features", []))
        choices = {}
        for name in names:
            versions = [v for v in rows_by_version[name]
                        if v not in blocked.get(name, [])
                        and (name not in pins or pins[name] == v)]
            choices[name] = [None] + versions

        best_score = None
        best_versions = None
        score_names = sorted(names, reverse=True)
        for values in product(*(choices[name] for name in names)):
            installed = dict(zip(names, values))
            if any(installed.get(name) is None
                   or not bounds[0] <= installed[name] <= bounds[1]
                   for name, bounds in data["roots"].items()):
                continue

            reached = set()
            graph = {}
            pending = [(name, bounds[0], bounds[1])
                       for name, bounds in data["roots"].items()]
            feasible = True
            while pending and feasible:
                name, low, high = pending.pop()
                version = installed.get(name)
                if version is None or not low <= version <= high:
                    feasible = False
                    break
                if name in reached:
                    continue
                reached.add(name)
                row = rows_by_version[name][version]
                active = [dep for dep in row.get("deps", [])
                          if not dep.get("feature") or dep["feature"] in features]
                graph[name] = [dep["name"] for dep in active]
                for dep in active:
                    pending.append((dep["name"], dep["min"], dep["max"]))
            if not feasible or reached != {n for n, v in installed.items() if v is not None}:
                continue

            finished, active_nodes = set(), set()
            def visit(name):
                if name in active_nodes:
                    return False
                if name in finished:
                    return True
                active_nodes.add(name)
                if any(not visit(dep) for dep in graph.get(name, [])):
                    return False
                active_nodes.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in graph):
                continue
            score = tuple(installed[name] if installed[name] is not None else -1
                          for name in score_names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: version for name, version in installed.items()
                                  if version is not None}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}

    return solve


def _build_component_07():
    from collections import Counter
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for selected in combinations(options, k):
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in selected)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in data.get("quotas", {}).items()):
                continue
            if any(sum(job["start"] <= time < job["end"] for job in selected) > 2
                   for time in (job["start"] for job in selected)):
                continue

            value = sum(job["value"] for job in selected)
            selected_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value
                    or (value == best_value and selected_ids > best_ids)):
                best_value, best_ids = value, selected_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_node = data["source"]
        start_mask = bit_for.get(start_node, 0)
        start_state = (start_node, start_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], start_node, start_mask, data["coupons"])]

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_remaining in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask,
                                               next_remaining))

        return {"arrival": None}

    return solve


